import type {
  ActionRow,
  IdentityRow,
  RowModel,
} from '@onekeyfe/react-native-native-list';

export const ACCOUNT_SELECTOR_WALLET_COUNT = 1_000;
export const ACCOUNT_SELECTOR_ACCOUNTS_PER_WALLET = 1_000;
export const ACCOUNT_SELECTOR_LOGICAL_ACCOUNT_COUNT =
  ACCOUNT_SELECTOR_WALLET_COUNT * ACCOUNT_SELECTOR_ACCOUNTS_PER_WALLET;
export const ACCOUNT_SELECTOR_ACCOUNT_CACHE_LIMIT = 3;

const referenceWalletNames = [
  'Wallet 1',
  'Wallet 1',
  'TEST',
  'Wallet 7',
  'Wallet 5',
  'Wallet 6',
  '观察钱包',
] as const;

const walletEmojis = ['🐼', '🐷', '🐺', '🐼', '🐱', '🐻', '👁️'] as const;

// The reference selector renders these same app-monorepo wallet avatar PNGs.
// Data URIs keep the standalone example self-contained on both native targets.
const walletAvatarUris = [
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
] as const;

const polarBearAvatarUri = 'data:image/png;base64,';

// Native versions of AccountAvatar consume blockie data URIs. These eight
// deterministic 40px blockies are reused across the stress data so rapid
// scrolling exercises image-view reuse without depending on the network.
const accountAvatarUris = [
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
  'data:image/png;base64,',
] as const;

export function walletKey(walletIndex: number): string {
  return `wallet-${walletIndex}`;
}

export function accountKey(walletIndex: number, accountIndex: number): string {
  return `account-${walletIndex}-${accountIndex}`;
}

export function walletName(walletIndex: number): string {
  return referenceWalletNames[walletIndex] ?? `Wallet ${walletIndex + 1}`;
}

export function walletEmoji(walletIndex: number): string {
  return walletEmojis[walletIndex % walletEmojis.length];
}

export function walletAvatarUri(walletIndex: number): string | undefined {
  if (walletIndex === 5) return polarBearAvatarUri;
  return walletAvatarUris[walletIndex];
}

export function parseWalletKey(key: string): number | undefined {
  const match = /^wallet-(\d+)$/.exec(key);
  if (!match) return undefined;
  const index = Number(match[1]);
  return index >= 0 && index < ACCOUNT_SELECTOR_WALLET_COUNT
    ? index
    : undefined;
}

export function parseAccountKey(
  key: string,
): { walletIndex: number; accountIndex: number } | undefined {
  const match = /^account-(\d+)-(\d+)$/.exec(key);
  if (!match) return undefined;
  const walletIndex = Number(match[1]);
  const accountIndex = Number(match[2]);
  if (
    walletIndex < 0 ||
    walletIndex >= ACCOUNT_SELECTOR_WALLET_COUNT ||
    accountIndex < 0 ||
    accountIndex >= ACCOUNT_SELECTOR_ACCOUNTS_PER_WALLET
  ) {
    return undefined;
  }
  return { walletIndex, accountIndex };
}

export function buildWalletRows(): readonly IdentityRow[] {
  return Array.from(
    { length: ACCOUNT_SELECTOR_WALLET_COUNT },
    (_, walletIndex): IdentityRow => {
      const key = walletKey(walletIndex);
      const avatarUri = walletAvatarUri(walletIndex);
      return {
        type: 'identity',
        key,
        groupId: key,
        groupPosition: 'single',
        presentation: 'walletSidebar',
        leading: {
          kind: 'wallet',
          image: avatarUri
            ? {
                uri: avatarUri,
                width: 40,
                height: 40,
                cachePolicy: 'memory',
                loadingStrategy: 'none',
              }
            : undefined,
          fallbackText: walletEmoji(walletIndex),
          backgroundColor: '#00000000',
        },
        title: walletName(walletIndex),
        accessibilityLabel: `${walletName(walletIndex)}, wallet ${
          walletIndex + 1
        } of ${ACCOUNT_SELECTOR_WALLET_COUNT}`,
      };
    },
  );
}

export function buildAccountRow(
  walletIndex: number,
  accountIndex: number,
): IdentityRow {
  const key = accountKey(walletIndex, accountIndex);
  const avatarIndex =
    walletIndex === 2 && accountIndex < 3
      ? accountIndex
      : (walletIndex * 7 + accountIndex) % accountAvatarUris.length;
  const hasValue = accountIndex === 0 || accountIndex % 20 === 0;
  const value =
    walletIndex === 2 && accountIndex === 0
      ? '$53.61'
      : hasValue
      ? `$${((walletIndex + 1) * (accountIndex + 1) * 0.37).toFixed(2)}`
      : '--';
  return {
    type: 'identity',
    presentation: 'accountSelector',
    key,
    groupId: key,
    groupPosition: 'single',
    leading: {
      kind: 'account',
      image: {
        uri: accountAvatarUris[avatarIndex],
        width: 40,
        height: 40,
        cachePolicy: 'memory',
        loadingStrategy: 'none',
      },
      shape: 'rounded',
    },
    title: `Account #${accountIndex + 1}`,
    subtitle: value,
    trailing: [
      {
        kind: 'icon',
        name: 'DotHorOutline',
        tintColor: '#FFFFFF64',
        actionKey: `account.more.${walletIndex}.${accountIndex}`,
      },
    ],
    accessibilityLabel: `${walletName(walletIndex)}, Account #${
      accountIndex + 1
    }, account ${
      accountIndex + 1
    } of ${ACCOUNT_SELECTOR_ACCOUNTS_PER_WALLET}, ${value}`,
  };
}

const addAccountRow: ActionRow = {
  type: 'action',
  presentation: 'accountSelector',
  key: 'account-add',
  title: '添加账户',
  actionKey: 'account.add',
  tone: 'neutral',
  icon: {
    kind: 'icon',
    name: 'PlusSmallOutline',
    shape: 'rounded',
    tintColor: '#FFFFFFAF',
    backgroundColor: '#FFFFFF12',
  },
  accessibilityLabel: '添加账户',
};

export function buildAccountRows(walletIndex: number): readonly IdentityRow[] {
  const rows: IdentityRow[] = [];
  for (
    let accountIndex = 0;
    accountIndex < ACCOUNT_SELECTOR_ACCOUNTS_PER_WALLET;
    accountIndex += 1
  ) {
    rows.push(buildAccountRow(walletIndex, accountIndex));
  }
  return rows;
}

export function buildVisibleAccountRows(
  accountRows: readonly IdentityRow[],
  searchText: string,
): readonly RowModel[] {
  const normalized = searchText.trim().toLocaleLowerCase();
  if (normalized) {
    return accountRows.filter(row =>
      row.title.toLocaleLowerCase().includes(normalized),
    );
  }
  return [...accountRows.slice(0, 3), addAccountRow, ...accountRows.slice(3)];
}

export class AccountRowsCache {
  private readonly rowsByWallet = new Map<number, readonly IdentityRow[]>();

  constructor(private readonly limit = ACCOUNT_SELECTOR_ACCOUNT_CACHE_LIMIT) {
    if (!Number.isInteger(limit) || limit < 1) {
      throw new RangeError('cache limit must be a positive integer');
    }
  }

  get(walletIndex: number): readonly IdentityRow[] {
    const cached = this.rowsByWallet.get(walletIndex);
    if (cached) {
      this.rowsByWallet.delete(walletIndex);
      this.rowsByWallet.set(walletIndex, cached);
      return cached;
    }

    const rows = buildAccountRows(walletIndex);
    this.rowsByWallet.set(walletIndex, rows);
    while (this.rowsByWallet.size > this.limit) {
      const oldestWallet = this.rowsByWallet.keys().next().value;
      if (oldestWallet === undefined) break;
      this.rowsByWallet.delete(oldestWallet);
    }
    return rows;
  }

  get cachedWalletCount(): number {
    return this.rowsByWallet.size;
  }

  get cachedRowCount(): number {
    return Array.from(this.rowsByWallet.values()).reduce(
      (total, rows) => total + rows.length,
      0,
    );
  }

  get cachedWalletIndexes(): readonly number[] {
    return Array.from(this.rowsByWallet.keys());
  }
}
